const $=id=>document.getElementById(id);
const nav=[['dashboard','⌗','Beranda'],['closing','⊕','Input Closing'],['ranking','▥','Ranking'],['visits','⌖','Kunjungan'],['history','◴','Riwayat']];
const meta={dashboard:['Dashboard Saya','Ringkasan aktivitas dan pencapaian Anda bulan ini.','Oktober 2026'],supervisor:['Dashboard Supervisor','Pantau aktivitas, pelaporan, dan performa seluruh tim.','Oktober 2026'],closing:['Input Closing','Catat aktivitas penjualan dengan detail yang tepat.','Oktober 2026'],ranking:['Ranking Tim','Ranking berdasarkan total closing seluruh produk.','Oktober 2026'],visits:['Dokumentasi Kunjungan','Catat kunjungan dan tindak lanjut aktivitas lapangan Anda.','25 Oktober 2026'],history:['Riwayat Laporan','Tinjau kembali catatan closing dan detail aktivitas Anda.','Oktober 2026']};
const staff=[['SA','Staff A',40],['NF','Saya',32],['SC','Staff C',28],['SD','Staff D',23],['SE','Staff E',19],['SF','Staff F',17]];
const activities=[['⌗','QRIS','Registrasi Baru · Toko Berkah','25 Okt 2026','+2'],['♢','Tabungan Emas','Pembukaan Baru','24 Okt 2026','+1'],['⌂','BSI Agen','Akuisisi Baru · Warung Makmur','24 Okt 2026','+1']];
const closingHistory=[['2026-10-25','QRIS','Registrasi Baru · Toko Berkah',2],['2026-10-24','Tabungan Emas','Pembukaan Baru',1],['2026-10-24','BSI Agen','Akuisisi Baru · Warung Makmur',1]];
let state={page:'dashboard',role:'staff',product:'QRIS'};
document.querySelector('.side-nav').innerHTML=nav.map(([id,ic,label])=>`<button data-route="${id}"><i>${ic}</i>${label}</button>`).join('');
document.querySelector('.mobile-nav').innerHTML=nav.map(([id,ic,label])=>`<button data-route="${id}"><i>${ic}</i><span>${label}</span></button>`).join('');
$('activityList').innerHTML=activities.map(a=>`<div class="activity"><i>${a[0]}</i><div><b>${a[1]}</b><span>${a[2]}</span></div><strong>${a[4]}</strong><small>${a[3]}</small></div>`).join('');
function rows(count=3){return staff.slice(0,count).map((s,i)=>`<div class="staff-row ${i===1?'me':''}"><span class="number">0${i+1}</span><i>${s[0]}</i><b>${s[1]}</b><strong>${s[2]}</strong></div>`).join('')}
$('topThree').innerHTML=rows(3);$('superRanking').innerHTML=rows(4);
$('fullRanking').innerHTML=staff.map((s,i)=>`<div class="rank-row ${i===1?'me':''}"><span>0${i+1}</span><i>${s[0]}</i><div><b>${s[1]}</b><small>${i===1?'Anda · ':''}Jakarta Saharjo</small></div><strong>${s[2]} <small>closing</small></strong></div>`).join('');
$('monitoringTable').innerHTML=`<div class="monitor-head"><span>Staff</span><span>QRIS</span><span>Emas</span><span>Agen</span><span>Closing</span></div>`+staff.map((s,i)=>`<div class="monitor-row ${i===1?'me':''}"><span><i>${s[0]}</i><b>${s[1]}</b>${i===1?'<em>Anda</em>':''}</span><span>${[17,12,9,8,7,6][i]}</span><span>${[12,11,10,8,6,5][i]}</span><span>${[11,9,9,7,6,6][i]}</span><strong>${s[2]}</strong></div>`).join('');
function renderProducts(){const products=['QRIS','BSI Agen','Tabungan Emas','EDC','Tabungan','Cicil Emas'];$('productPicker').innerHTML=products.map((p,i)=>`<button type="button" data-product="${p}" class="${p===state.product?'active':''}"><i>${['⌗','⌂','♢','▭','▣','▱'][i]}</i>${p}<span>${p===state.product?'✓':''}</span></button>`).join('');document.querySelectorAll('[data-product]').forEach(b=>b.onclick=()=>{state.product=b.dataset.product;$('selectedProductName').textContent=state.product;renderProducts()})}renderProducts();
$('visitCards').innerHTML=[['Toko Makmur','Kunjungan Merchant','25 Okt 2026','Follow up kerja sama'],['Resto Sejahtera','Aktivasi EDC','24 Okt 2026','Pengecekan perangkat']].map(v=>`<article class="visit-card"><div class="placeholder">⌁ &nbsp; Pratinjau tidak tersedia</div><h3>${v[0]} <span>⌖</span></h3><div><b>${v[1]}</b><small>${v[2]}</small></div><p>${v[3]}</p></article>`).join('');
function renderHistory(){const q=$('historySearch').value.toLowerCase();const data=closingHistory.filter(h=>h.join(' ').toLowerCase().includes(q));$('historyContent').innerHTML=`<div class="history-head"><span>Tanggal</span><span>Staff</span><span>Produk</span><span>Nama / Aktivitas</span><span>Jumlah</span><span>Aksi</span></div>`+data.map(h=>`<div class="history-row"><span>${h[0]}</span><span><i>NF</i><b>Saya</b></span><span><em class="${h[1].includes('Emas')?'gold':''}">${h[1]}</em></span><b>${h[2]}</b><strong>${h[3]}</strong><button>⌕ Edit</button></div>`).join('')}renderHistory();
function route(page){state.page=page;if(page==='supervisor')state.role='supervisor';else if(page==='dashboard')state.role='staff';document.querySelectorAll('.page').forEach(p=>p.classList.toggle('active',p.id===page));document.querySelectorAll('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===page));document.querySelectorAll('[data-role]').forEach(b=>b.classList.toggle('active',b.dataset.role===state.role));document.querySelectorAll('.avatar').forEach(a=>a.textContent=state.role==='staff'?'NF':'SP');const m=meta[page];$('pageTitle').textContent=m[0];$('pageSubtitle').textContent=m[1];$('dateLabel').textContent=m[2];$('crumb').textContent=m[0];history.replaceState(null,'','#'+page);window.scrollTo(0,0)}
document.addEventListener('click',e=>{const r=e.target.closest('[data-route]');if(r)route(r.dataset.route);const role=e.target.closest('[data-role]');if(role)route(role.dataset.role==='supervisor'?'supervisor':'dashboard')});
document.querySelectorAll('.segments button').forEach(b=>b.onclick=()=>document.querySelectorAll('.segments button').forEach(x=>x.classList.toggle('active',x===b)));
document.querySelectorAll('.radio').forEach(l=>l.onclick=()=>document.querySelectorAll('.radio').forEach(x=>x.classList.toggle('active',x===l)));
document.querySelectorAll('.categories label').forEach(l=>l.onclick=()=>document.querySelectorAll('.categories label').forEach(x=>x.classList.toggle('active',x===l)));
['closingForm','visitForm'].forEach(id=>$(id).addEventListener('submit',e=>{e.preventDefault();e.currentTarget.querySelector('.success').hidden=false}));
$('historySearch').addEventListener('input',renderHistory);route(meta[location.hash.slice(1)]?location.hash.slice(1):'dashboard');
